mapper.select:
SELECT pp.no AS pp_no, pp.user_nickname AS userNickname, pp.title, pp.description, pp.thumbnail, pp.created_at AS createdAt, pp.updated_at AS updatedAt, pp.user_no AS userNo, pp.fork_count AS forkCount, pp.liked_count AS likedCount, pp.view_count AS viewCount, pp.start_day AS startDay, pp.end_day AS endDay, pp.total_member AS totalMember,
pt.no AS tag_no, pt.plan_post_no AS tag_plan_post_no, pt.name AS tag_name
FROM plan_post pp JOIN plan_attraction_detail pad ON pp.no = pad.plan_post_no LEFT JOIN plan_post_tag pt ON pp.no = pt.plan_post_no
WHERE pad.attraction_no = #{attractionNo}
ORDER BY pp.created_at DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE attractions
SET ratingSum = IFNULL(ratingSum, 0) + #{rating}
WHERE no = #{attractionNo}

UPDATE attractions
SET ratingSum = IFNULL(ratingSum, 0) - #{rating}
WHERE no = #{attractionNo}

UPDATE attractions
SET reviewCount = IFNULL(reviewCount, 0) + 1
WHERE no = #{attractionNo}

UPDATE attractions
SET reviewCount = IFNULL(reviewCount, 0) - 1
WHERE no = #{attractionNo}
